--
-- TOC entry 535 (class 1255 OID 20679)
-- Name: ins_issue_after(); Type: FUNCTION; Schema: public; Owner: squashtm
--

CREATE FUNCTION public.ins_issue_after() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
      BEGIN
        INSERT INTO EXECUTION_ISSUES_CLOSURE (execution_id, issue_id)
        SELECT COALESCE(ex.execution_id, ees.execution_id, sn.execution_id),
               NEW.issue_id
        FROM ISSUE AS i
               LEFT JOIN EXECUTION AS ex ON i.issue_list_id = ex.issue_list_id
               LEFT JOIN EXECUTION_STEP AS es ON i.issue_list_id = es.issue_list_id
               LEFT JOIN EXECUTION_EXECUTION_STEPS AS ees ON es.execution_step_id = ees.execution_step_id
               LEFT JOIN SESSION_NOTE AS sn ON i.issue_list_id = sn.issue_list_id
        WHERE i.issue_id = NEW.issue_id
          AND COALESCE(ex.execution_id, ees.execution_id, sn.execution_id) IS NOT NULL;

        RETURN NEW;
      END;
      $$;


ALTER FUNCTION public.ins_issue_after() OWNER TO squashtm;

